const std=@import("std");const M=@import("microbes.zig");const B=@import("baseline.zig");const R=@import("root_mutation.zig");const E=std.testing.expect;
fn fixture(comptime T:type,seed:u64,root:f32)T.Cell{var c=T.initialized(seed);c.cohorts[0]=.{.biomass=0.125,.support_mass=0.03125,.organization=0.25,.lineage=17,.generation=2,.reproduction_credit=0.125,.root_fraction=root};return c;}
fn oldEqual(a:M.Cell,b:B.Cell)!void{try E(a.rng==b.rng and a.nutrient==b.nutrient and a.detritus==b.detritus);for(a.cohorts,b.cohorts)|x,y|inline for(std.meta.fields(B.Cohort))|f|{if(comptime !std.mem.eql(u8,f.name,"root_fraction"))try std.testing.expectEqual(@field(y,f.name),@field(x,f.name));};}
test "actual funded birth legacy fields six draws and cost"{var positive:usize=0;for(0..4096)|n|{const root: f32=if(n%2==0)0 else 0.5;var d=fixture(M,n+1,root);var b=fixture(B,n+1,root);var t=M.initialized(5);var bt=B.initialized(5);var st=M.Stats{.next_lineage=n+100};var bs=B.Stats{.next_lineage=n+100};const same=n%3==0;const dst=if(same)&d else &t;const bdst=if(same)&b else &bt;const cfg=R.Config{.law=1,.enabled=n%4!=0,.stream_seed=42};const ok=if(n%3==2)M.propagateWithRoot(&d,0,dst,&st,cfg)else M.reproduceWithRoot(&d,0,dst,&st,true,cfg);const bok=if(n%3==2)B.propagate(&b,0,bdst,&bs)else B.reproduce(&b,0,bdst,&bs,true);try E(ok and bok);try oldEqual(d,b);try oldEqual(t,bt);inline for(std.meta.fields(B.Stats))|f|try std.testing.expectEqual(@field(bs,f.name),@field(st,f.name));const child=dst.cohorts[if(same)@as(usize,1)else 0];const want=if(cfg.enabled)R.allocation(root,42,17,n+100,3)else root;try E(child.root_fraction==want and child.root_fraction>=0 and child.root_fraction<=1);try E(M.abovegroundSupport(child)==child.support_mass*(1-child.root_fraction));try E(d.cohorts[0].root_fraction==root);if(root==0 and child.root_fraction>0)positive+=1;}try E(positive>0);std.debug.print("FUNDED 4096 oldfields_stats_rng_exact positive_from_zero={d}\n",.{positive});}
test "proposal distribution clipping reproducibility"{var plus:usize=0;var minus:usize=0;for(0..65536)|i|{const p=R.proposal(42,17,i+100,3);try E(p==R.proposal(42,17,i+100,3));if(p>0)plus+=1;if(p<0)minus+=1;try E(R.allocation(0,42,17,i+100,3)==@max(0,p));try E(R.allocation(1,42,17,i+100,3)==@min(1,1+p));}try E(plus>400 and plus<650 and minus>400 and minus<650);std.debug.print("PROPOSALS n=65536 plus={d} minus={d} clipping_negative_zero=true\n",.{plus,minus});}
test "failed paid checks and invalid law atomic; mutate false exact inheritance"{for(0..6)|k|{var d=fixture(M,1,0.25);var t=M.initialized(5);var st=M.Stats{.next_lineage=100};var cfg=R.Config{.law=1,.enabled=true,.stream_seed=42};switch(k){0=>d.cohorts[0].biomass=0.001,1=>d.cohorts[0].reproduction_credit=0,2=>{for(&t.cohorts)|*c|c.*=.{.biomass=0.1};},3=>cfg.law=2,4=>cfg.law=0,5=>d.cohorts[0].root_fraction=2,else=>unreachable}const a=d;const b=t;const s=st;try E(!M.reproduceWithRoot(&d,0,&t,&st,true,cfg));try std.testing.expectEqualDeep(a,d);try std.testing.expectEqualDeep(b,t);try std.testing.expectEqualDeep(s,st);}var d=fixture(M,1,0.25);var t=M.initialized(5);var st=M.Stats{.next_lineage=100};try E(M.reproduceWithRoot(&d,0,&t,&st,false,.{.law=1,.enabled=true,.stream_seed=42}));try E(t.cohorts[0].root_fraction==0.25 and d.rng==1);}
test "actual movement and mortality identity no phantom descendants"{const env=M.Environment{.temperature=303,.depth_km=0.002,.light=1,.carbon_available=100,.oxygen_carbon_capacity=100};var cells=[_]M.Cell{fixture(M,1,0.25),M.initialized(2)};cells[0].cohorts[0].mobility=1;cells[0].cohorts[0].feeding=1;cells[1].cohorts[0]=.{.biomass=0.3,.lineage=50};const result=M.relocate(&cells,0,0,env,&.{.{.index=1,.environment=env}},86400000,17);try E(result.moved);try E(cells[0].cohorts[0].biomass==0 and cells[1].cohorts[1].lineage==17 and cells[1].cohorts[1].root_fraction==0.25);var dead=fixture(M,1,0.25);var lethal=env;lethal.temperature=500;lethal.light=0;_=M.step(&dead,lethal,86400000);try E(dead.cohorts[0].biomass==0);for(dead.cohorts[1..])|c|try E(c.biomass==0);std.debug.print("IDENTITY relocation_preserved=true mortality_no_descendant=true\n",.{});}
test "independent Python SHA256 endian vector and config identity"{var bytes:[32]u8=undefined;const expected=try std.fmt.hexToBytes(&bytes,"7daa6503978fdaa8f8088f1f28719bb7ae57c6e884c33e0e9c7019b9d1827f75");try std.testing.expectEqualSlices(u8,expected,&R.digest(42,17,123456,2));const c=R.Config{.law=1,.enabled=false,.stream_seed=std.math.maxInt(u64)};const a=std.testing.allocator;const text=try std.json.stringifyAlloc(a,c,.{});defer a.free(text);const parsed=try std.json.parseFromSlice(R.Config,a,text,.{});defer parsed.deinit();try std.testing.expectEqualDeep(c,parsed.value);try E(parsed.value.valid() and !(R.Config{.law=0,.stream_seed=1}).valid());}
